{"command":"$path='C:\WeGameApps\rail_apps\OasisEraEditor(2001776)\ShadowTrackerExtra\Saved\Profiling\CSV\Profile(20260711_111520).csv'
$rows = Import-Csv -LiteralPath $path | Where-Object { $_.Time -and $_.Time -notlike 'EVENTS*' -and $_.Time -notlike '[*' }
$stats = foreach ($col in 'Create','Update','Flush','Audio') {
  $vals = $rows | ForEach-Object { [double]$_.$col }
  $nonZero = @($vals | Where-Object { $_ -ne 0 })
  [pscustomobject]@{
    Metric=$col
    Rows=$vals.Count
    NonZero=$nonZero.Count
    Max=($vals | Measure-Object -Maximum).Maximum
    Avg=([math]::Round(($vals | Measure-Object -Average).Average,4))
    NonZeroAvg=if($nonZero.Count){[math]::Round(($nonZero | Measure-Object -Average).Average,4)}else{0}
  }
}
$topCreate = $rows | Sort-Object {[double]$_.Create} -Descending | Select-Object -First 10 Time,Create,'COUNTS/Create',Update,'COUNTS/Update'
$topUpdate = $rows | Sort-Object {[double]$_.Update} -Descending | Select-Object -First 10 Time,Create,'COUNTS/Create',Update,'COUNTS/Update'
$topCounts = $rows | Sort-Object {[int]$_.'COUNTS/Update'} -Descending | Select-Object -First 10 Time,Create,'COUNTS/Create',Update,'COUNTS/Update'
$gaps = New-Object System.Collections.Generic.List[object]
$prev=$null
foreach($r in $rows){
  if($r.Time -match '^(\d+)\.(\d+)\.(\d+):(\d+)$'){
    $t = ([int]$matches[1])*3600000 + ([int]$matches[2])*60000 + ([int]$matches[3])*1000 + ([int]$matches[4])
    if($prev -ne $null){
      $gap = $t - $prev.t
      if($gap -gt 100){ $gaps.Add([pscustomobject]@{From=$prev.time; To=$r.Time; GapMs=$gap}) }
    }
    $prev=[pscustomobject]@{time=$r.Time;t=$t}
  }
}
