{"command":"$path='C:\WeGameApps\rail_apps\OasisEraEditor(2001776)\ShadowTrackerExtra\Saved\Profiling\CSV\Profile(20260711_111520).csv'
$rows = Import-Csv -LiteralPath $path | Where-Object { $_.Time -match '^\d+\.\d+\.\d+:\d+$' }
function Num($x) { if ([string]::IsNullOrWhiteSpace($x)) { 0.0 } else { [double]$x } }
function IntNum($x) { if ([string]::IsNullOrWhiteSpace($x)) { 0 } else { [int]$x } }
$stats = foreach ($col in 'Create','Update','Flush','Audio') {
  $vals = @($rows | ForEach-Object { Num $_.$col })
  $nonZero = @($vals | Where-Object { $_ -ne 0 })
  [pscustomobject]@{
    Metric=$col
    Rows=$vals.Count
    NonZero=$nonZero.Count
    Max=($vals | Measure-Object -Maximum).Maximum
    Avg=([math]::Round(($vals | Measure-Object -Average).Average,4))
    NonZeroAvg=if($nonZero.Count){[math]::Round(($nonZero | Measure-Object -Average).Average,4)}else{0}
  }
}
$topCreate = $rows | Sort-Object { Num $_.Create } -Descending | Select-Object -First 8 Time,Create,'COUNTS/Create',Update,'COUNTS/Update'
$topUpdate = $rows | Sort-Object { Num $_.Update } -Descending | Select-Object -First 8 Time,Create,'COUNTS/Create',Update,'COUNTS/Update'
$topCounts = $rows | Sort-Object { IntNum $_.'COUNTS/Update' } -Descending | Select-Object -First 8 Time,Create,'COUNTS/Create',Update,'COUNTS/Update'
$gaps = New-Object System.Collections.Generic.List[object]
$prev=$null
foreach($r in $rows){
  if($r.Time -match '^(\d+)\.(\d+)\.(\d+):(\d+)$'){
    $t = ([int]$matches[1])*3600000 + ([int]$matches[2])*60000 + ([int]$matches[3])*1000 + ([int]$matches[4])
    if($prev -ne $null){
      $gap = $t - $prev.t
      if($gap -gt 100){ $gaps.Add([pscustomobject]@{From=$prev.time; To=$r.Time; GapMs=$gap}) }
    }
    $prev=[pscustomobject]@{time=$r.Time;t=$t}
  }
}
$item = Get-Item -LiteralPath $path
Write-Output "FILE`t$($item.FullName)`tLength=$($item.Length)`tLastWrite=$($item.LastWriteTime.ToString('yyyy-MM-dd HH:mm:ss'))"
Write-Output "ROWS`t$($rows.Count)`tFirst=$($rows[0].Time)`tLast=$($rows[-1].Time)"
Write-Output 'STATS'
$stats | ConvertTo-Csv -NoTypeInformation
Write-Output 'TOP_CREATE'
$topCreate | ConvertTo-Csv -NoTypeInformation
Write-Output 'TOP_UPDATE'
$topUpdate | ConvertTo-Csv -NoTypeInformation
Write-Output 'TOP_UPDATE_COUNTS'
$topCounts | ConvertTo-Csv -NoTypeInformation
Write-Output 'GAPS_GT_100MS'
